use moloch_replay::session::Session;
use serde_json::{Value,json};
use sha2::{Digest,Sha256};
use std::{path::PathBuf,sync::atomic::{AtomicU64,Ordering}};
const BASE:i64=1_792_022_400_000;
fn iso(n:i64)->String{chrono::DateTime::from_timestamp_millis(BASE+n).unwrap().to_rfc3339_opts(chrono::SecondsFormat::Millis,true)}
fn hash(v:&Value)->String{format!("{:x}",Sha256::digest(serde_json::to_vec(v).unwrap()))}
struct F{bank:Option<Session>,root:PathBuf,seq:u64,policy:Value,seed:Value}
impl Drop for F{fn drop(&mut self){self.bank.take();let _=std::fs::remove_dir_all(&self.root);}}
impl F{
 fn new()->Self{static NEXT:AtomicU64=AtomicU64::new(0);let root=std::env::temp_dir().join(format!("probabilistic-native-{}-{}",std::process::id(),NEXT.fetch_add(1,Ordering::Relaxed)));let policy=json!({"initialCash":"100.000000","maximumCommitted":"40.000000","maximumMarketCost":"10.000000","quantity":20,"maximumMarkets":3,"minimumSpreadTicks":1000,"entryStopAt":iso(100000)});let seed=json!({"runId":"prob-run","availableCash":"100.000000","accountSnapshotHash":"a".repeat(64),"observedAt":iso(0)});let bank=Session::open_live(&root,&policy,&seed).unwrap();let mut f=Self{bank:Some(bank),root,seq:0,policy,seed};f.put(book("101",0)).unwrap();f}
 fn bank(&self)->&Session{self.bank.as_ref().unwrap()}
 fn put(&mut self,e:Value)->Result<(),Box<dyn std::error::Error>>{let next=self.seq+1;self.bank.as_mut().unwrap().accept("prob-test",next,&e)?;self.seq=next;Ok(())}
 fn deny(&mut self,e:Value){let report=self.bank().engine().report().unwrap();let orders=self.bank().engine().order_records();let head=self.bank().durable_head();assert!(self.put(e).is_err());assert_eq!(self.bank().engine().report().unwrap(),report);assert_eq!(self.bank().engine().order_records(),orders);assert_eq!(self.bank().durable_head(),head);}
 fn reserve(&self)->Value{let b=&self.bank().engine().live_package_books()[0];let legs=json!([{"marketId":"101","exchangeId":"101","side":"YES","action":"buy","quantity":5,"limitPrice":"0.450000","bookHash":hash(b)}]);let qualification=json!({"version":1,"kind":"reviewed_probabilistic_portfolio","planSha256":"a".repeat(64),"modelSha256":"b".repeat(64),"semanticReviewSha256":"c".repeat(64),"policySha256":"d".repeat(64),"dispatchSha256":"e".repeat(64),"positionsSha256":hash(&self.bank().engine().wallet.positions()),"validUntilMs":BASE+60000,"contracts":[{"marketId":"101","exchangeId":"101","contractId":"201","side":"YES","officialRootSha256":"f".repeat(64)}],"states":[{"id":"win","weightPpm":950000,"outcomes":["resolvedYes"]},{"id":"lose","weightPpm":50000,"outcomes":["resolvedNo"]}],"risk":{"minimumExpectedGain":"0.100000","maximumIncrementalCvarLoss":"3.000000","maximumTerminalCvarLoss":"3.000000","tailPpm":100000,"maximumGrossBuyFunding":"10.000000","capitalRatePpmPerDay":0,"horizonMs":300000,"factors":{}},"metrics":{"expectedIncrementNumerator":"2500000000000","incrementalCvarLoss":"1.125000","terminalCvarLoss":"1.125000","minimumModeledIncrement":"-2.250000","grossBuyFunding":"2.250000","minimumSellProceeds":"0.000000","capitalOpportunityCost":"0.000000"},"wireLegs":legs});json!({"type":"probabilistic_portfolio_reserve_v1","source":"moloch_live_dispatcher","receivedAt":iso(1),"processedAt":iso(1),"packageId":"prob-package","proofHash":hash(&qualification),"bankScope":{"runId":"prob-run","bankManifestHash":self.bank().manifest_hash(),"tournamentId":"cup"},"bankHead":self.bank().durable_head(),"expectedReportSha256":hash(&self.bank().engine().report().unwrap()),"expiresAt":iso(9000),"qualification":qualification,"legs":legs})}
 fn restart(&mut self){self.bank.take();self.bank=Some(Session::open_live(&self.root,&self.policy,&self.seed).unwrap());}
}
fn book(ex:&str,at:i64)->Value{json!({"type":"book","receivedAt":iso(at),"book":{"marketId":ex,"exchangeId":ex,"tournamentId":"cup","sequence":(at+1).to_string(),"sourceAt":iso(at),"requestStartedAt":iso(at),"receivedAt":iso(at),"bids":[{"price":"0.400000","quantity":20}],"asks":[{"price":"0.450000","quantity":20}]}})}
fn seal(r:&mut Value){r["qualification"]["wireLegs"]=r["legs"].clone();r["proofHash"]=json!(hash(&r["qualification"]));}
fn event(r:&Value,kind:&str,at:i64)->Value{json!({"type":kind,"source":"moloch_live_dispatcher","receivedAt":iso(at),"processedAt":iso(at),"packageId":r["packageId"],"proofHash":r["proofHash"],"bankScope":r["bankScope"],"requestHash":"a".repeat(64),"idempotencyKey":"prob-run:prob-package","bookHashes":{"101":r["legs"][0]["bookHash"]}})}
fn actual(q:&Value,kind:&str,n:u64,at:i64)->Value{json!({"type":kind,"source":"official_sig_api_v1","receiptHash":"d".repeat(64),"orderId":q["id"],"actualOrderId":"9001","exchangeId":q["exchangeId"],"marketId":q["marketId"],"side":q["side"],"action":q["action"],"quantity":n,"price":q["price"],"fee":"0.000000","fillId":format!("800{at}"),"receivedAt":iso(at),"executedAt":iso(at),"filledQuantity":n,"fillsComplete":true,"status":if n==5{"filled"}else{"canceled"}})}
#[test]fn genuine_session_reserve_debits_no_cash_and_records_no_guaranteed_floor(){let mut f=F::new();let r=f.reserve();assert!(f.bank().engine().report().unwrap().get("livePackages").is_none());f.put(r).unwrap();let e=f.bank().engine();assert_eq!(e.report().unwrap()["reservedCash"],"2.250000");assert_eq!(e.report().unwrap()["cash"],"100.000000");assert!(e.fills().is_empty());assert!(e.package_blocks_submissions());assert_eq!(e.package_records()[0]["probabilistic"]["guaranteedArbitrage"],false);assert!(e.package_records()[0]["economics"].get("minimumPayout").is_none());}
#[test]fn probability_expected_value_and_cvar_are_recomputed_not_trusted(){for case in ["expectation","cvar","mass","refund","negative","dimension","duplicate"]{let mut f=F::new();let mut r=f.reserve();match case{"expectation"=>r["qualification"]["metrics"]["expectedIncrementNumerator"]=json!("2500000000001"),"cvar"=>r["qualification"]["metrics"]["incrementalCvarLoss"]=json!("0.000000"),"mass"=>r["qualification"]["states"][1]["weightPpm"]=json!(49999),"refund"=>r["qualification"]["states"][1]["outcomes"][0]=json!("refundPrincipal"),"negative"=>{r["qualification"]["states"][0]["weightPpm"]=json!(100000);r["qualification"]["states"][1]["weightPpm"]=json!(900000);},"dimension"=>r["qualification"]["states"][1]["outcomes"]=json!([]),_=>r["qualification"]["states"][1]["id"]=json!("win")};seal(&mut r);f.deny(r);}}
#[test]fn reviewed_tail_funding_factor_and_native_caps_deny_atomic_reservation(){for case in ["tail","funding","factor","quantity","market","entry"]{let mut f=F::new();let mut r=f.reserve();match case{"tail"=>r["qualification"]["risk"]["maximumIncrementalCvarLoss"]=json!("1.000000"),"funding"=>r["qualification"]["risk"]["maximumGrossBuyFunding"]=json!("2.000000"),"factor"=>r["qualification"]["risk"]["factors"]=json!({"national":{"maximumAbsoluteSharesMicros":"0","loadingPpm":["1000000"]}}),"quantity"=>r["legs"][0]["quantity"]=json!(21),"market"=>{r["legs"][0]["quantity"]=json!(20);r["legs"][0]["limitPrice"]=json!("0.995000");},_=>r["expiresAt"]=json!(iso(100001))};seal(&mut r);f.deny(r);}}
#[test]fn exact_session_head_positions_scope_and_current_depth_are_mandatory(){for case in ["head","report","positions","scope","depth","hash","expiry","uncovered"]{let mut f=F::new();let mut r=f.reserve();match case{"head"=>r["bankHead"]["sequence"]=json!(999),"report"=>r["expectedReportSha256"]=json!("f".repeat(64)),"positions"=>r["qualification"]["positionsSha256"]=json!("f".repeat(64)),"scope"=>r["bankScope"]["runId"]=json!("foreign"),"depth"=>r["legs"][0]["limitPrice"]=json!("0.440000"),"hash"=>r["legs"][0]["bookHash"]=json!("f".repeat(64)),"expiry"=>r["expiresAt"]=json!(iso(3001)),_=>r["legs"][0]["action"]=json!("sell")};seal(&mut r);f.deny(r);}}
#[test]fn old_floor_and_new_probability_transition_classes_cannot_mix(){let mut f=F::new();let r=f.reserve();f.put(r.clone()).unwrap();let old=event(&r,"live_package_attempt",3001);f.deny(old);f.put(event(&r,"probabilistic_portfolio_attempt_v1",3001)).unwrap();f.deny(event(&r,"live_package_unknown",3002));let mut wrong=r.clone();wrong["type"]=json!("live_package_reserve");let mut other=F::new();other.deny(wrong);}
#[test]fn ordinary_tick_and_expiry_cannot_release_unknown_or_reserved_funding(){let mut f=F::new();let r=f.reserve();f.put(r.clone()).unwrap();f.put(event(&r,"probabilistic_portfolio_attempt_v1",3001)).unwrap();f.put(event(&r,"probabilistic_portfolio_unknown_v1",3002)).unwrap();f.put(json!({"type":"tick","receivedAt":iso(20000)})).unwrap();assert_eq!(f.bank().engine().report().unwrap()["reservedCash"],"2.250000");assert!(f.bank().engine().order_records().iter().all(|q|q["retired"]==false));assert!(f.bank().engine().package_blocks_submissions());}
#[test]fn actual_partial_fill_and_terminal_release_only_unexecuted_funding_then_restart_blocks(){let mut f=F::new();let r=f.reserve();f.put(r.clone()).unwrap();f.put(event(&r,"probabilistic_portfolio_attempt_v1",3001)).unwrap();let q=f.bank().engine().order_records()[0].clone();f.put(actual(&q,"actual_order_ack",5,3002)).unwrap();assert!(f.bank().engine().fills().is_empty());f.put(actual(&q,"actual_fill",1,3003)).unwrap();assert_eq!(f.bank().engine().report().unwrap()["reservedCash"],"1.800000");f.put(actual(&q,"actual_order_terminal",1,3004)).unwrap();assert_eq!(f.bank().engine().report().unwrap()["reservedCash"],"0.000000");assert_eq!(f.bank().engine().wallet.quantity("101",moloch_replay::Side::Yes),1);f.deny(event(&r,"probabilistic_portfolio_complete_v1",3005));let report=f.bank().engine().report().unwrap();f.restart();assert_eq!(f.bank().engine().report().unwrap(),report);assert!(f.bank().engine().package_blocks_submissions());}
#[test]fn completion_requires_actual_full_fills_and_keeps_remaining_portfolio_protected(){let mut f=F::new();let r=f.reserve();f.put(r.clone()).unwrap();f.put(event(&r,"probabilistic_portfolio_attempt_v1",3001)).unwrap();let q=f.bank().engine().order_records()[0].clone();f.put(actual(&q,"actual_order_ack",5,3002)).unwrap();f.deny(event(&r,"probabilistic_portfolio_complete_v1",3003));f.put(actual(&q,"actual_fill",5,3004)).unwrap();f.put(actual(&q,"actual_order_terminal",5,3005)).unwrap();f.put(event(&r,"probabilistic_portfolio_complete_v1",3006)).unwrap();assert_eq!(f.bank().engine().report().unwrap()["cash"],"97.750000");assert_eq!(f.bank().engine().report().unwrap()["realized"],"0.000000");f.put(json!({"type":"tick","receivedAt":iso(20000)})).unwrap();assert_eq!(f.bank().engine().order_records().len(),1);assert_eq!(f.bank().engine().wallet.quantity("101",moloch_replay::Side::Yes),5);let report=f.bank().engine().report().unwrap();f.restart();assert_eq!(f.bank().engine().report().unwrap(),report);}
#[test]fn typed_never_attempted_release_is_financially_neutral_and_id_cannot_reuse(){let mut f=F::new();let r=f.reserve();f.put(r.clone()).unwrap();let mut z=event(&r,"probabilistic_portfolio_no_execution_v1",2);z["evidence"]=json!({"kind":"never_attempted","confirmedNetworkAttempts":0});f.put(z).unwrap();assert_eq!(f.bank().engine().report().unwrap()["reservedCash"],"0.000000");assert_eq!(f.bank().engine().report().unwrap()["cash"],"100.000000");let mut repeat=r.clone();repeat["bankHead"]=f.bank().durable_head();repeat["expectedReportSha256"]=json!(hash(&f.bank().engine().report().unwrap()));f.deny(repeat);}
#[test]fn refund_returns_new_principal_and_does_not_turn_cancelled_state_into_win(){let mut f=F::new();let mut r=f.reserve();r["qualification"]["states"][0]["weightPpm"]=json!(900000);r["qualification"]["states"][1]["weightPpm"]=json!(100000);r["qualification"]["states"][1]["outcomes"][0]=json!("refundPrincipal");r["qualification"]["metrics"]["expectedIncrementNumerator"]=json!("2475000000000");for key in ["incrementalCvarLoss","terminalCvarLoss","minimumModeledIncrement"]{r["qualification"]["metrics"][key]=json!("0.000000");}seal(&mut r);f.put(r).unwrap();assert!(f.bank().engine().fills().is_empty());assert_eq!(f.bank().engine().report().unwrap()["cash"],"100.000000");}
#[test]fn covered_sell_consumes_actual_fifo_instead_of_average_cost(){let mut f=F::new();
 // Exact adopted principal is 1.8 + 2.199999, not an invented weighted basis.
 let mut adoption=json!({"type":"actual_position_adoption","source":"official_sig_api_v1","authority":"human_moloch_inherited_management_20261015","complete":true,"receiptHash":"d".repeat(64),"requestStartedAt":iso(-1),"receivedAt":iso(0),"processedAt":iso(0),"tournamentId":"cup","openingCost":"4.000000","effectiveMaximumMarkets":4,"positions":[{"exchangeId":"101","marketId":"101","quantity":5,"lotPrincipal":"4.000000","reportedCostBasis":"4.000000","reportedMinusLotPrincipal":"0.000000","basisClassification":"exact","lots":[{"lotId":"501","quantity":2,"side":"YES","entryPrice":"0.900000","openedAt":iso(-86400000)},{"lotId":"502","quantity":3,"side":"YES","entryPrice":"0.733333","openedAt":iso(-43200000)}]}]});
 adoption["openingCost"]=json!("3.999999");adoption["positions"][0]["lotPrincipal"]=json!("3.999999");adoption["positions"][0]["reportedCostBasis"]=json!("3.999999");f.put(adoption).unwrap();let mut r=f.reserve();r["legs"][0]["action"]=json!("sell");r["legs"][0]["quantity"]=json!(2);r["legs"][0]["limitPrice"]=json!("0.400000");r["qualification"]["states"][0]["weightPpm"]=json!(200000);r["qualification"]["states"][1]["weightPpm"]=json!(800000);r["qualification"]["risk"]["maximumTerminalCvarLoss"]=json!("4.000000");r["qualification"]["metrics"]=json!({"expectedIncrementNumerator":"400000000000","incrementalCvarLoss":"1.200000","terminalCvarLoss":"3.199999","minimumModeledIncrement":"-1.200000","grossBuyFunding":"0.000000","minimumSellProceeds":"0.800000","capitalOpportunityCost":"0.000000"});seal(&mut r);f.put(r.clone()).unwrap();assert_eq!(f.bank().engine().report().unwrap()["reservedCash"],"0.000000");f.put(event(&r,"probabilistic_portfolio_attempt_v1",3001)).unwrap();let q=f.bank().engine().order_records()[0].clone();f.put(actual(&q,"actual_order_ack",2,3002)).unwrap();f.put(actual(&q,"actual_fill",2,3003)).unwrap();assert_eq!(f.bank().engine().report().unwrap()["realized"],"-1.000000");assert_eq!(f.bank().engine().wallet.positions()["101"]["YES"][0]["price"],"0.733333");assert_eq!(f.bank().engine().wallet.quantity("101",moloch_replay::Side::Yes),3);}
